import{_ as n,l,o as e,c as i,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"集合覆盖贪心","description":"","frontmatter":{"title":"集合覆盖贪心","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/set-cover-greedy.md","filePath":"cs/set-cover-greedy.md","lastUpdated":1789023840000}'),c={name:"cs/set-cover-greedy.md"};function _(m,a,f,u,P,A){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="集合覆盖贪心" tabindex="-1">集合覆盖贪心 <a class="header-anchor" href="#集合覆盖贪心" aria-label="Permalink to &quot;集合覆盖贪心&quot;">​</a></h1><div class="epigraph"><p>每次选覆盖新元素最多的集合，近似比 $H_n\\le \\ln n+1$；除非 P=NP 没有 $o(\\log n)$ 多项式近似。</p><footer>—— 据 Johnson, Approximation Algorithms for Combinatorial Problems, 1974；Chvátal, 1979；CLRS 第 35.3 节整理</footer></div><p>上一课<a href="/cs/vertex-cover-approx">顶点覆盖 2 近似</a>是集合覆盖的特殊（每元素度 2 时更紧）。一般集合覆盖：宇宙 \\(n\\) 元素，集合族。缺口是贪心 \\(H_n\\)。不重写匹配。后课 Christofides TSP。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每次选 \\(\\max\\) 新覆盖数的集合。分析：未覆盖元素对 OPT 的「价钱」分摊，\\(k\\) 个剩余时本次代价 \\(\\le\\mathrm{OPT}/k\\)，调和数相加 \\(H_n\\)。加权 Chvátal：性价比 \\(w(S)/\\)新元素。</p><p>缺口是调和比，不是 2。</p><h3 id="顶点覆盖不是" tabindex="-1">顶点覆盖不是 \\(\\ln n\\) <a class="header-anchor" href="#顶点覆盖不是" aria-label="Permalink to &quot;顶点覆盖不是 $\\ln n$&quot;">​</a></h3><p>元素 = 边、集合 = 顶点的关联星时，贪心度仍可能差；用上一课匹配。问题结构决定比。</p><p><span class="marginnote">Johnson 1974。Chvátal 加权。Feige $ (1-\\varepsilon)\\ln n $ 硬度。后课度量 TSP Christofides。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>集合用链表或倒排。每步扫未删集合。实现 \\(O(\\sum |S|)\\) 量级。</p>',11)),(e(),s(p,null,{default:r(()=>[h(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E6%9C%AA%E8%A6%86%E7%9B%96%22%5D%20--%3E%20GRD%5B%22%E9%80%89%E6%80%A7%E4%BB%B7%E6%AF%94%E6%9C%80%E5%A4%A7%22%5D%0A%20%20GRD%20--%3E%20HN%5B%22%E6%AF%94%20%E2%89%A4%20H_n%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>精确指数：状压 \\(n\\) 小。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分摊：OPT 的某个集合覆盖了当前剩余里的 \\(k&#39;\\)，贪心不差于「平均」。调和来自 \\(1+1/2+\\cdots\\)。与子模最大化同类贪心。与 LP：对偶拟合给同一 \\(H_n\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Feige 硬度全文。不写部分覆盖。后课默认：集合覆盖贪心 \\(H_n\\)。下一课 Christofides。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>贪心性价比，\\(H_n\\)-近似。</li><li>对数比本质（硬度）。</li><li>特殊图结构可用更紧算法。</li><li>出处：Johnson, 1974；Chvátal, 1979；CLRS 第 35.3 节。</li></ul>',7))])}const b=n(c,[["render",_]]);export{C as __pageData,b as default};
